  (hf : PowerSeries.constantCoeff f = 0) : MvPowerSeries.constantCoeff (PowerSeries.subst a f) = 0

theorem PowerSeries.subst_X_comp_const.{u_2, u_3} {R : Type u_2} [CommRing R] {τ : Type u_3}
  {f : PowerSeries R} {i : τ} :
  MvPowerSeries.subst (MvPowerSeries.X ∘ fun x => i) f = PowerSeries.subst (MvPowerSeries.X i) f

theorem PowerSeries.le_order_subst_right'.{u_2} {R : Type u_2} [CommRing R] {f φ : PowerSeries R}
  (hf : PowerSeries.constantCoeff f = 0) (hφ : PowerSeries.constantCoeff φ = 0) :
  f.order ≤ PowerSeries.order (PowerSeries.subst f φ)

theorem PowerSeries.HasSubst.add.{u_2, u_3} {R : Type u_2} [CommRing R] {τ : Type u_3}
  {f g : MvPowerSeries τ R} (hf : PowerSeries.HasSubst f) (hg : PowerSeries.HasSubst g) :
  PowerSeries.HasSubst (f + g)

theorem PowerSeries.substAlgHom_coe.{u_2, u_3, u_4} {R : Type u_2} [CommRing R] {τ : Type u_3}
  {S : Type u_4} [CommRing S] [Algebra R S] {a : MvPowerSeries τ S} (ha : PowerSeries.HasSubst a)
  (p : Polynomial R) : (PowerSeries.substAlgHom ha) ↑p = (Polynomial.aeval a) p

theorem PowerSeries.subst_coe.{u_2, u_3, u_4} {R : Type u_2} [CommRing R] {τ : Type u_3} {S : Type u_4}
  [CommRing S] [Algebra R S] {a : MvPowerSeries τ S} (ha : PowerSeries.HasSubst a)
  (p : Polynomial R) : PowerSeries.subst a ↑p = (Polynomial.aeval a) p
